    var parts = month.split('-');
    return MONTHS[Number(parts[1]) - 1] + ' ' + parts[0];
  }
  function issuePath(month) { return '/newsletter/' + month + '/'; }
  function absolute(url) { return /^https?:/.test(url) ? url : SITE + url; }

  /* The plain-page template (tools/page-template.html), filled the way tools/build_pages.mjs fills it. */
  function fill(template, meta, content) {
    return template.replace(/<!-- Template for[\s\S]*?-->\n/, '').replace(/\{\{(\w+)\}\}/g, function (match, key) {
      if (key === 'content') return content;
      if (key === 'url') return esc(SITE + meta.path);
      if (key in meta) return esc(meta[key]);
      throw new Error('page-template.html: no value for ' + match);
    });
  }

  function itemHtml(item) {
    var title = item.url ? '<a href="' + esc(item.url) + '">' + esc(item.title) + '</a>' : esc(item.title);
    return '        <li class="nl-item">' +
      (item.meta ? '<span class="nl-item-meta">' + esc(item.meta) + '</span>' : '') +
      '<h3>' + title + '</h3>' +
      (item.text ? '<p>' + esc(item.text) + '</p>' : '') + '</li>';
  }
  function sectionHtml(section) {
    var body = section.items && section.items.length
      ? '      <ul class="nl-items">\n' + section.items.map(itemHtml).join('\n') + '\n      </ul>'
      : '      <p>' + esc(section.empty || '') + '</p>';
    return '    <section class="nl-section" aria-labelledby="nl-' + esc(section.id) + '">\n' +
      '      <h2 id="nl-' + esc(section.id) + '">' + esc(section.title) + '</h2>\n' + body +
      (section.note ? '\n      <p class="nl-section-note">' + esc(section.note) + '</p>' : '') + '\n    </section>';
  }

  function issuePage(issue, template) {
    var name = monthName(issue.month);
    var content = [
      '    <p class="doc-eyebrow"><a href="/newsletter/">What’s on in Ghana</a></p>',
      '    <h1>' + esc(name) + '. <em>' + esc(issue.headline || 'What’s on in Ghana this month.') + '</em></h1>',
      '    <p class="info-updated">Sent ' + esc(issue.sentOn || name) + '</p>',
      '    <p class="info-lead">' + esc(issue.intro) + '</p>',
      issue.sections.map(sectionHtml).join('\n\n'),
      '    <p class="nl-more"><a href="/newsletter/">← All issues</a></p>',
      '    <section class="nl-band nl-page-band" aria-label="Newsletter sign-up" data-newsletter="newsletter"></section>'
    ].join('\n');
    return fill(template, {
      path: issuePath(issue.month),
      title: 'What’s on in Ghana: ' + name + ' · GhanaNice',
      description: issue.preheader || issue.intro
    }, content);
  }

  /* What the archive needs to know about each issue, kept in dist/data/newsletter-issues.json so
     the workflow can rebuild the archive (and avoid repeating a place or tip) without the
     full issue files. */
  function summary(issue) {
    return { month: issue.month, title: monthName(issue.month), url: issuePath(issue.month), headline: issue.headline || '', intro: issue.intro, used: issue.used || {} };
  }

  function archivePage(summaries, template) {
    var list = summaries.length
      ? '    <ul class="info-list nl-archive">\n' + summaries.map(function (s) {
          return '      <li><a class="info-inline" href="' + esc(s.url) + '"><strong>' + esc(s.title) + '</strong></a>' +
            (s.headline ? ' · ' + esc(s.headline) : '') + '</li>';
        }).join('\n') + '\n    </ul>'
      : '    <p>No issues yet. Sign up above and the first one comes straight to you.</p>';
    var content = [
      '    <p class="doc-eyebrow">Newsletter</p>',
      '    <h1>What’s on in Ghana. <em>One email a month.</em></h1>',
      '    <p class="info-lead">Near the end of each month: the festivals coming up next month, what’s new on GhanaNice, one place worth the trip and a tip from a reader. Every issue is also published here.</p>',
      '    <section class="nl-band nl-page-band" aria-label="Newsletter sign-up" data-newsletter="newsletter"></section>',
      '    <h2>Past issues</h2>',
      list
    ].join('\n');
    return fill(template, {
      path: '/newsletter/',
      title: 'What’s on in Ghana: the GhanaNice newsletter',
      description: 'A monthly email from GhanaNice: next month’s festivals, new places, one place worth the trip and a tip from a reader. Read past issues here.'
    }, content);
  }

  /* The sitemap entries for the newsletter, in the order tools/build_regions.mjs writes them. */
  function sitemapUrls(summaries) {
    return [SITE + '/newsletter/'].concat(summaries.slice().sort(function (a, b) { return a.month < b.month ? -1 : 1; })
      .map(function (s) { return SITE + s.url; }));
  }

  /* The issue as email, laid out to paste into MailerLite's editor: plain HTML with inline
     styles and absolute links. */
  function emailHtml(issue) {
    var font = 'font-family:Arial,Helvetica,sans-serif;';
    var serif = 'font-family:Georgia,\'Times New Roman\',serif;';
    var out = ['<div style="max-width:620px;' + serif + 'color:#11110f;font-size:16px;line-height:1.5">',
      '<p style="' + font + 'font-size:11px;font-weight:bold;letter-spacing:.12em;text-transform:uppercase;color:#df4a32;margin:0 0 8px">What’s on in Ghana · ' + esc(monthName(issue.month)) + '</p>',
      '<h1 style="' + font + 'font-size:30px;line-height:1.05;margin:0 0 14px">' + esc(issue.headline || 'What’s on in Ghana this month.') + '</h1>',
      '<p style="margin:0 0 22px">' + esc(issue.intro) + '</p>'];
    issue.sections.forEach(function (section) {
      out.push('<h2 style="' + font + 'font-size:20px;margin:28px 0 10px;padding-top:14px;border-top:2px solid #11110f">' + esc(section.title) + '</h2>');
      if (!section.items || !section.items.length) out.push('<p style="margin:0 0 12px">' + esc(section.empty || '') + '</p>');
      (section.items || []).forEach(function (item) {
        out.push('<p style="margin:0 0 14px">' +
          (item.meta ? '<span style="' + font + 'font-size:11px;font-weight:bold;letter-spacing:.08em;text-transform:uppercase;color:#5c5b55">' + esc(item.meta) + '</span><br>' : '') +
          '<strong style="' + font + 'font-size:17px">' + (item.url ? '<a href="' + esc(absolute(item.url)) + '" style="color:#11110f">' + esc(item.title) + '</a>' : esc(item.title)) + '</strong>' +
          (item.text ? '<br>' + esc(item.text) : '') + '</p>');
      });
      if (section.note) out.push('<p style="margin:0 0 12px;font-size:14px;color:#5c5b55">' + esc(section.note) + '</p>');
    });
    out.push('<p style="margin:28px 0 0;padding-top:14px;border-top:2px solid #11110f">Know a festival or a place we should add? Reply to this email, or <a href="' + SITE + '/#tip" style="color:#11110f">share it on GhanaNice</a>.</p>');
    out.push('<p style="margin:10px 0 0;font-size:14px;color:#5c5b55">Read this issue on the site: <a href="' + SITE + issuePath(issue.month) + '" style="color:#5c5b55">' + SITE.replace('https://', '') + issuePath(issue.month) + '</a></p>');
    out.push('</div>');
    return out.join('\n');
  }

  return { SITE: SITE, MONTHS: MONTHS, esc: esc, monthName: monthName, issuePath: issuePath, issuePage: issuePage, archivePage: archivePage, summary: summary, sitemapUrls: sitemapUrls, emailHtml: emailHtml };
})();

// Put the issue together: the facts from "Gather issue" with Claude's short copy laid over them.
// If Claude's reply is missing or unreadable, the data's own wording is used, so an issue is
// always drafted. Produces the issue (as stored in tools/newsletter/<yyyy-mm>.json), the
// paste-ready email for August and the MailerLite draft campaign.
// GhanaNiceNewsletter (tools/newsletter-render.js) is pasted in above this by the builder.
const R = GhanaNiceNewsletter;
const GROUP_ID = '201520530803656462';
const SENDER = { from: 'hello@ghananice.com', from_name: 'GhanaNice' };
const REVIEW_TO = 'augustministry@gmail.com';
const { facts, month } = $('Gather issue').first().json;

let ai = {};
let aiProblem = '';
const reply = $input.first().json;
const block = (reply.content || []).find(b => b.type === 'text');
try {
  const text = (block?.text || '').replace(/^```(?:json)?\s*|\s*```$/g, '');
  ai = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
} catch {
  aiProblem = reply.error ? `Claude returned an error (${reply.error.message || reply.error.type}).` : 'Claude’s reply could not be read.';
}
const line = (value, max) => typeof value === 'string' && value.trim() ? value.trim().slice(0, max) : '';
const name = `${facts.monthName} ${facts.year}`;

const festivalItems = [
  ...facts.festivals.map(f => ({
    meta: `${f.region} · ${f.when}`,
    title: f.name,
    url: `/festivals/${f.slug}/`,
    text: [line(ai.festivals?.[f.slug], 260) || f.sum, f.dateSetBy ? `Dates set by ${f.dateSetBy.replace(/\.$/, '')}.` : ''].filter(Boolean).join(' ')
  })),
  ...facts.akwasidae.map(f => ({
    meta: `${f.region} · ${f.dates.join(' and ')}`,
    title: f.name,
    url: `/festivals/${f.slug}/`,
    text: `${line(ai.festivals?.[f.slug], 260) || f.sum} The dates follow the 42-day Akan calendar; check with Manhyia Palace before you travel.`
  }))
];

const newItems = [];
if (facts.newFestivals.length > 4) {
  newItems.push({ meta: 'Festivals', title: `${facts.newFestivals.length} festivals and cultural events`, url: '/festivals/',
    text: line(ai.newFestivals, 300) || `A month-by-month list of festivals across all 16 regions, from ${facts.newFestivals.slice(0, 3).join(', ')} and more.` });
} else {
  facts.newFestivals.forEach(n => newItems.push({ meta: 'Festivals', title: n, url: '/festivals/', text: '' }));
}
facts.newTips.forEach(t => newItems.push({
  meta: [t.category, t.area].filter(Boolean).join(' · '), title: t.place, url: t.regionSlug ? `/regions/${t.regionSlug}/` : '/', text: t.note || ''
}));
facts.newServices.forEach(s => newItems.push({
  meta: `Travel directory · ${s.category}`, title: s.name, url: '/travel-directory.html', text: s.description.slice(0, 220)
}));

const place = facts.place;
const tip = facts.tip;
const issue = {
  month,
  subject: line(ai.subject, 90) || `What’s on in Ghana: ${name}`,
  preheader: line(ai.preheader, 140) || `Festivals in ${facts.monthName}, what’s new on GhanaNice and a tip from a reader.`,
  headline: line(ai.headline, 100) || 'What’s on in Ghana this month.',
  intro: line(ai.intro, 600) || `Here is what’s coming up across Ghana in ${facts.monthName}, what we added to GhanaNice this month, one place worth the trip and a tip from a reader.`,
  sections: [
    { id: 'festivals', title: `Festivals in ${facts.monthName}`, items: festivalItems,
      empty: `None of the festivals on our list falls in ${facts.monthName}. See the whole year on ghananice.com/festivals.`,
      note: festivalItems.length ? 'Most festival dates are set each year by the chiefs and traditional councils who keep them, so treat these as approximate and check the festival page close to the time.' : '' },
    { id: 'new', title: 'New on GhanaNice', items: newItems,
      empty: 'Nothing new went up this month. Know a place we should add? Share it on GhanaNice.' },
    { id: 'place', title: 'One place worth the trip', items: [{
      meta: `${place.region} Region`, title: place.name, url: `/regions/${place.regionSlug}/`, text: line(ai.place, 400) || place.note }] },
    { id: 'tip', title: 'A tip from a reader', items: tip ? [{
      meta: [tip.region, tip.area].filter(Boolean).join(' · '), title: tip.place, url: tip.regionSlug ? `/regions/${tip.regionSlug}/` : '/',
      text: `“${tip.note}”${tip.by ? ` – ${tip.by}` : ''}` }] : [],
      empty: 'No new reader tips this month. Been somewhere good? Share it on GhanaNice and it could be here next month.' }
  ],
  used: { place: place.key, tipId: tip ? tip.id : '' }
};

const campaign = {
  name: `What’s on in Ghana – ${name}`,
  type: 'regular',
  emails: [{ subject: issue.subject, ...SENDER }],
  groups: [GROUP_ID]
};

return [{ json: { issue, campaign, aiProblem, name, reviewTo: REVIEW_TO, email: R.emailHtml(issue) } }];

const a = $('Assemble issue').first().json;
const res = $input.first().json;
const ok = res.statusCode >= 200 && res.statusCode < 300 && res.body?.data?.id;
const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const problems = [
  a.aiProblem ? `${a.aiProblem} The issue below uses the site’s own wording instead; read it through.` : '',
  ok ? '' : `MailerLite didn’t create the draft (${res.statusCode || 'no answer'}: ${esc(JSON.stringify(res.body || res.error || '').slice(0, 300))}). Create it by hand: Campaigns → Create campaign → Regular, subject below, sender hello@ghananice.com, group “GhanaNice newsletter”.`
].filter(Boolean);
const box = 'font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;background:#f1eee5;border:1px solid #11110f;padding:16px 18px;margin:0 0 28px;max-width:620px';
const html = `<div style="${box}">
<p style="margin:0 0 10px"><b>The ${esc(a.name)} issue is drafted.</b></p>
${problems.map(p => `<p style="margin:0 0 10px;color:#b3261e"><b>Check:</b> ${p}</p>`).join('\n')}
<ol style="margin:0 0 10px;padding-left:20px">
<li>In MailerLite, open <b>Campaigns → Drafts → “What’s on in Ghana – ${esc(a.name)}”</b>${ok ? '' : ' (once you’ve created it)'}. Subject, sender (hello@ghananice.com) and the GhanaNice newsletter group are already set.</li>
<li>Choose the design (the first time, pick a simple layout; after that, duplicate last month’s and swap the text), then paste the issue below. Check every link opens.</li>
<li>Preview text: <i>${esc(a.issue.preheader)}</i></li>
<li>Schedule it for the last days of the month, e.g. the 28th at 9:00.</li>
<li>After it has gone out, open the second email, “Publish the ${esc(a.name)} issue on the site?”, and click <b>Sent: publish it</b>.</li>
</ol>
<p style="margin:0">Subject: <b>${esc(a.issue.subject)}</b></p>
</div>
${a.email}`;
return [{ json: {
  campaignId: ok ? res.body.data.id : '',
  draftSubject: `Newsletter: the ${a.name} issue is ready to paste`,
  draftHtml: html,
  askSubject: `Publish the ${a.name} issue on the site?`,
  askText: `When the ${a.name} issue has gone out from MailerLite, click “Sent: publish it” and it goes on ghananice.com/newsletter/${a.issue.month}/ with the archive and sitemap. If you’re skipping this month, click “Don’t publish”. This request expires after 30 days.`
} }];

/* Renders the monthly newsletter, "What's on in Ghana", from one issue's data
   (tools/newsletter/<yyyy-mm>.json). Shared by two callers, so both always produce the same
   bytes:
   - tools/build_newsletter.mjs, which writes /newsletter/ and the issue pages (and is run with
     --check by tools/smoke.mjs);
   - the n8n issue workflow (n8n/build_newsletter_issue_workflow.py pastes this file into its Code
     nodes), which drafts the email and, once August has sent it, commits the issue page.
   Plain script, no imports: it defines one global, GhanaNiceNewsletter. All issue text is plain
   text and is escaped here; URLs are root-relative site paths. */
var GhanaNiceNewsletter = (function () {
  var SITE = 'https://www.ghananice.com';
  var MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  function esc(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function monthName(month) {
    var parts = month.split('-');
    return MONTHS[Number(parts[1]) - 1] + ' ' + parts[0];
  }
  function issuePath(month) { return '/newsletter/' + month + '/'; }
  function absolute(url) { return /^https?:/.test(url) ? url : SITE + url; }

  /* The plain-page template (tools/page-template.html), filled the way tools/build_pages.mjs fills it. */
  function fill(template, meta, content) {
    return template.replace(/<!-- Template for[\s\S]*?-->\n/, '').replace(/\{\{(\w+)\}\}/g, function (match, key) {
      if (key === 'content') return content;
      if (key === 'url') return esc(SITE + meta.path);
      if (key in meta) return esc(meta[key]);
      throw new Error('page-template.html: no value for ' + match);
    });
  }

  function itemHtml(item) {
    var title = item.url ? '<a href="' + esc(item.url) + '">' + esc(item.title) + '</a>' : esc(item.title);
    return '        <li class="nl-item">' +
      (item.meta ? '<span class="nl-item-meta">' + esc(item.meta) + '</span>' : '') +
      '<h3>' + title + '</h3>' +
      (item.text ? '<p>' + esc(item.text) + '</p>' : '') + '</li>';
  }
  function sectionHtml(section) {
    var body = section.items && section.items.length
      ? '      <ul class="nl-items">\n' + section.items.map(itemHtml).join('\n') + '\n      </ul>'
      : '      <p>' + esc(section.empty || '') + '</p>';
    return '    <section class="nl-section" aria-labelledby="nl-' + esc(section.id) + '">\n' +
      '      <h2 id="nl-' + esc(section.id) + '">' + esc(section.title) + '</h2>\n' + body +
      (section.note ? '\n      <p class="nl-section-note">' + esc(section.note) + '</p>' : '') + '\n    </section>';
  }

  function issuePage(issue, template) {
    var name = monthName(issue.month);
    var content = [
      '    <p class="doc-eyebrow"><a href="/newsletter/">What’s on in Ghana</a></p>',
      '    <h1>' + esc(name) + '. <em>' + esc(issue.headline || 'What’s on in Ghana this month.') + '</em></h1>',
      '    <p class="info-updated">Sent ' + esc(issue.sentOn || name) + '</p>',
      '    <p class="info-lead">' + esc(issue.intro) + '</p>',
      issue.sections.map(sectionHtml).join('\n\n'),
      '    <p class="nl-more"><a href="/newsletter/">← All issues</a></p>',
      '    <section class="nl-band nl-page-band" aria-label="Newsletter sign-up" data-newsletter="newsletter"></section>'
    ].join('\n');
    return fill(template, {
      path: issuePath(issue.month),
      title: 'What’s on in Ghana: ' + name + ' · GhanaNice',
      description: issue.preheader || issue.intro
    }, content);
  }

  /* What the archive needs to know about each issue, kept in dist/data/newsletter-issues.json so
     the workflow can rebuild the archive (and avoid repeating a place or tip) without the
     full issue files. */
  function summary(issue) {
    return { month: issue.month, title: monthName(issue.month), url: issuePath(issue.month), headline: issue.headline || '', intro: issue.intro, used: issue.used || {} };
  }

  function archivePage(summaries, template) {
    var list = summaries.length
      ? '    <ul class="info-list nl-archive">\n' + summaries.map(function (s) {
          return '      <li><a class="info-inline" href="' + esc(s.url) + '"><strong>' + esc(s.title) + '</strong></a>' +
            (s.headline ? ' · ' + esc(s.headline) : '') + '</li>';
        }).join('\n') + '\n    </ul>'
      : '    <p>No issues yet. Sign up above and the first one comes straight to you.</p>';
    var content = [
      '    <p class="doc-eyebrow">Newsletter</p>',
      '    <h1>What’s on in Ghana. <em>One email a month.</em></h1>',
      '    <p class="info-lead">Near the end of each month: the festivals coming up next month, what’s new on GhanaNice, one place worth the trip and a tip from a reader. Every issue is also published here.</p>',
      '    <section class="nl-band nl-page-band" aria-label="Newsletter sign-up" data-newsletter="newsletter"></section>',
      '    <h2>Past issues</h2>',
      list
    ].join('\n');
    return fill(template, {
      path: '/newsletter/',
      title: 'What’s on in Ghana: the GhanaNice newsletter',
      description: 'A monthly email from GhanaNice: next month’s festivals, new places, one place worth the trip and a tip from a reader. Read past issues here.'
    }, content);
  }

  /* The sitemap entries for the newsletter, in the order tools/build_regions.mjs writes them. */
  function sitemapUrls(summaries) {
    return [SITE + '/newsletter/'].concat(summaries.slice().sort(function (a, b) { return a.month < b.month ? -1 : 1; })
      .map(function (s) { return SITE + s.url; }));
  }

  /* The issue as email, laid out to paste into MailerLite's editor: plain HTML with inline
     styles and absolute links. */
  function emailHtml(issue) {
    var font = 'font-family:Arial,Helvetica,sans-serif;';
    var serif = 'font-family:Georgia,\'Times New Roman\',serif;';
    var out = ['<div style="max-width:620px;' + serif + 'color:#11110f;font-size:16px;line-height:1.5">',
      '<p style="' + font + 'font-size:11px;font-weight:bold;letter-spacing:.12em;text-transform:uppercase;color:#df4a32;margin:0 0 8px">What’s on in Ghana · ' + esc(monthName(issue.month)) + '</p>',
      '<h1 style="' + font + 'font-size:30px;line-height:1.05;margin:0 0 14px">' + esc(issue.headline || 'What’s on in Ghana this month.') + '</h1>',
      '<p style="margin:0 0 22px">' + esc(issue.intro) + '</p>'];
    issue.sections.forEach(function (section) {
      out.push('<h2 style="' + font + 'font-size:20px;margin:28px 0 10px;padding-top:14px;border-top:2px solid #11110f">' + esc(section.title) + '</h2>');
      if (!section.items || !section.items.length) out.push('<p style="margin:0 0 12px">' + esc(section.empty || '') + '</p>');
      (section.items || []).forEach(function (item) {
        out.push('<p style="margin:0 0 14px">' +
          (item.meta ? '<span style="' + font + 'font-size:11px;font-weight:bold;letter-spacing:.08em;text-transform:uppercase;color:#5c5b55">' + esc(item.meta) + '</span><br>' : '') +
          '<strong style="' + font + 'font-size:17px">' + (item.url ? '<a href="' + esc(absolute(item.url)) + '" style="color:#11110f">' + esc(item.title) + '</a>' : esc(item.title)) + '</strong>' +
          (item.text ? '<br>' + esc(item.text) : '') + '</p>');
      });
      if (section.note) out.push('<p style="margin:0 0 12px;font-size:14px;color:#5c5b55">' + esc(section.note) + '</p>');
    });
    out.push('<p style="margin:28px 0 0;padding-top:14px;border-top:2px solid #11110f">Know a festival or a place we should add? Reply to this email, or <a href="' + SITE + '/#tip" style="color:#11110f">share it on GhanaNice</a>.</p>');
    out.push('<p style="margin:10px 0 0;font-size:14px;color:#5c5b55">Read this issue on the site: <a href="' + SITE + issuePath(issue.month) + '" style="color:#5c5b55">' + SITE.replace('https://', '') + issuePath(issue.month) + '</a></p>');
    out.push('</div>');
    return out.join('\n');
  }

  return { SITE: SITE, MONTHS: MONTHS, esc: esc, monthName: monthName, issuePath: issuePath, issuePage: issuePage, archivePage: archivePage, summary: summary, sitemapUrls: sitemapUrls, emailHtml: emailHtml };
})();

// After August has sent the issue: the files for one commit that puts it on the site.
// The same renderer as tools/build_newsletter.mjs, fed the same inputs (the plain-page template,
// the issue list and the sitemap as they are on main now), so smoke's --check stays green.
// GhanaNiceNewsletter (tools/newsletter-render.js) is pasted in above this by the builder.
const R = GhanaNiceNewsletter;
const head = $('Git ref').first().json.object?.sha;
const baseTree = $('Git commit').first().json.tree?.sha;
if (!head || !baseTree) throw new Error('Could not read main from GitHub (check the GhanaNice — GitHub credential).');
const text = name => {
  const file = $(name).first().json;
  if (!file.content) throw new Error(`${name}: GitHub returned no file (${file.message || 'unknown error'}).`);
  return Buffer.from(file.content, 'base64').toString('utf8');
};
const template = text('Page template');
const sitemap = text('Sitemap');
let listed = [];
try { listed = JSON.parse(text('Issue list')).issues || []; } catch { listed = []; }

const sentOn = new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Africa/Accra' }).format(new Date());
const issue = { ...$('Assemble issue').first().json.issue, sentOn };
const summaries = [R.summary(issue), ...listed.filter(s => s.month !== issue.month)].sort((a, b) => (a.month < b.month ? 1 : -1));
const json = value => JSON.stringify(value, null, 1) + '\n';

const loc = `  <url><loc>${R.SITE}${R.issuePath(issue.month)}</loc></url>\n`;
const newSitemap = sitemap.includes(loc) ? sitemap : sitemap.replace('</urlset>', `${loc}</urlset>`);

const files = [
  [`tools/newsletter/${issue.month}.json`, json(issue)],
  [`dist/newsletter/${issue.month}/index.html`, R.issuePage(issue, template)],
  ['dist/newsletter/index.html', R.archivePage(summaries, template)],
  ['dist/data/newsletter-issues.json', json({ issues: summaries })],
  ['dist/sitemap.xml', newSitemap]
];
return files.map(([path, content]) => ({ json: {
  path, content: Buffer.from(content, 'utf8').toString('base64'), head, baseTree,
  message: `Newsletter: publish the ${R.monthName(issue.month)} issue\n\nSent from MailerLite and published by the n8n issue workflow.`,
  url: `${R.SITE}${R.issuePath(issue.month)}`
} }));

const files = $('Publish issue').all();
const tree = $input.all().map((blob, index) => {
  if (!blob.json.sha) throw new Error(`GitHub did not store ${files[index].json.path}`);
  return { path: files[index].json.path, mode: '100644', type: 'blob', sha: blob.json.sha };
});
const first = files[0].json;
return [{ json: { tree, baseTree: first.baseTree, head: first.head, message: first.message, url: first.url } }];
